package main
import("bytes";"fmt";"io";"net/http";"os";"strings";"time")
func main(){base:=os.Getenv("HANZO_BASE_URL");if base==""{base="https://api.hanzo.ai/v1"};key:=os.Getenv("HANZO_API_KEY");if key==""{panic("Set HANZO_API_KEY")};req,e:=http.NewRequest("POST",strings.TrimRight(base,"/")+"/worlds",bytes.NewBufferString(`{"model":"sekai-1-alpha","domain":"simulation"}`));if e!=nil{panic(e)};req.Header.Set("Authorization","Bearer "+key);req.Header.Set("Content-Type","application/json");client:=http.Client{Timeout:30*time.Second,CheckRedirect:func(r *http.Request,v []*http.Request)error{return http.ErrUseLastResponse}};r,e:=client.Do(req);if e!=nil{panic(e)};defer r.Body.Close();if r.StatusCode/100!=2{panic(r.Status)};b,e:=io.ReadAll(io.LimitReader(r.Body,1048576));if e!=nil{panic(e)};fmt.Println(string(b))}
